  "troubleshooting": [
   {
    "symptom": "Equipment does not restart immediately after a call",
    "causes": [
     "Equipment protection timers are running"
    ],
    "fixes": [
     "Documented timers: minimum compressor OFF 5 minutes, minimum compressor ON 4 minutes, minimum furnace ON 3 minutes, minimum furnace cycle time 6 minutes, minimum elapsed time between compressor activations 6 minutes.",
     "All protection timers except the compressor OFF timer can be overridden if a heating or cooling demand is initiated or terminated with the UP, DOWN, HEAT or COOL buttons.",
     "Both the minimum compressor OFF timer and the minimum equipment cycle timer can be overridden by pressing and holding either the HEAT or COOL button for 4 seconds."
    ]
   },
   {
    "symptom": "Heat does not operate at all",
    "causes": [
     "Thermostat has been stored or is being used at an ambient temperature above 93 deg F - the over-temperature thermal-mechanical switch has opened W1 (and W2 on the 51M35)"
    ],
    "fixes": [
     "Bring the thermostat below 93 deg F for about 30 minutes; the heat function is then re-enabled."
    ]
   },
   {
    "symptom": "All settings reverted to defaults",
    "causes": [
     "Power loss longer than 24 hours",
     "RESET button was pressed"
    ],
    "fixes": [
     "Reprogram. Note power must have been applied for at least six consecutive hours before a power loss for memory to be retained for the specified 24 hours."
    ]
   }
  ],
